from PIL import Image
import numpy as np
a = np.array(Image.open('image.png').convert('RGB')).astype(int)
bright = (a.sum(axis=2) > 600)
# simple flood-fill labeling
H,W = bright.shape
seen = np.zeros_like(bright)
blobs=[]
for y in range(H):
    for x in range(W):
        if bright[y,x] and not seen[y,x]:
            stack=[(y,x)]; seen[y,x]=True; pts=[]
            while stack:
                cy,cx=stack.pop(); pts.append((cy,cx))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<H and 0<=nx<W and bright[ny,nx] and not seen[ny,nx]:
                            seen[ny,nx]=True; stack.append((ny,nx))
            ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
            blobs.append((np.mean(xs),np.mean(ys),len(pts),min(xs),max(xs),min(ys),max(ys)))
print('bright blobs:', len(blobs))
for b in blobs: print('center (%.2f, %.2f) size %d bbox x%d-%d y%d-%d'%b)
"

